changeSet.sql:
INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Irlande – Oireachtas et Gouvernement', 'Députés (Dáil), sénateurs (Seanad), Taoiseach, ministres et ministres d''État, d''après l''API ouverte de l''Oireachtas, en fonction et sortis depuis moins de 12 mois (catégories IE-a et IE-b)', 'ie_pep_parliament', 'PEP', 'https://api.oireachtas.ie/', 'ie-pep-parliament', 'D:/test parser 2/plugins/swiftcheck-aml-ie-pep-parliament-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'API', NULL, '{"apiUrl": "https://api.oireachtas.ie/v1", "monthsAfterEnd": "12", "delayMs": "1000"}', 168, 12, 'Licence Oireachtas (PSI) / Creative Commons Attribution 4.0 : citer la source', 'Houses of the Oireachtas, api.oireachtas.ie', 'Environ 3 appels : liste des chambres, puis les membres du Dáil et du Seanad en cours (et des chambres terminées depuis moins de 12 mois). Fonctions (Taoiseach, ministres, ministres d''État, Ceann Comhairle) avec dates. L''API ne donne ni date de naissance ni sexe. Les décédés sont écartés.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', TRUE, 'Tous les membres du Dáil et du Seanad en fonction et sortis depuis moins de 12 mois, avec parti, circonscription ou panel et dates de mandat.', 'Ni date de naissance ni sexe dans l''API.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'IE-b' AND f.label IN ('Teachta Dála (député)', 'Sénateur', 'Ancien député ou sénateur') AND p.dataset_name = 'ie_pep_parliament';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', TRUE, 'Taoiseach, ministres et ministres d''État en fonction ou sortis depuis moins de 12 mois, avec dates de nomination et de fin, d''après les fonctions du membre à l''Oireachtas.', 'Seulement les membres de l''Oireachtas (tous les ministres irlandais le sont). Pas de fonction « Tánaiste » distincte dans l''API.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'IE-a' AND f.label IN ('Taoiseach, ministres et ministres d''État', 'Ancien membre du Gouvernement') AND p.dataset_name = 'ie_pep_parliament';
